import React, { useState, useEffect } from "react";
import api from "../../services/api";
import { API_ENDPOINTS } from "../../services/apiEndpoints";
import TweetCard from "../tweetCard";
import { closestCorners, DndContext } from "@dnd-kit/core";
import {
    SortableContext,
    verticalListSortingStrategy,
} from "@dnd-kit/sortable";
import Tweets from "../../pages/tweets";

const TweetList = ({ wallId }) => {
    const [tweets, setTweets] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);

    // Fetch tweets when the component mounts or wallId changes
    useEffect(() => {
        const fetchTweets = async () => {
            try {
                if (!wallId) {
                    throw new Error("Wall ID is required to fetch tweets");
                }
                const response = await api.get(
                    API_ENDPOINTS.GET_TWEETS_BY_WALL(wallId)
                );
                setTweets(response.data || []);
                setLoading(false);
            } catch (err) {
                console.error("Fetch Tweets Error:", err.message);
                setError(
                    err.response?.data?.message || "Failed to load tweets"
                );
                setLoading(false);
            }
        };

        fetchTweets();
    }, [wallId]);

    // Handle randomization of tweets via backend
    const handleRandomize = async () => {
        try {
            setError(null);
            if (tweets.length === 0) {
                setError("No tweets to randomize");
                return;
            }
            const response = await api.patch(
                API_ENDPOINTS.REORDER_TWEETS(wallId)
            );
            setTweets(response.data || []);
        } catch (err) {
            console.error("Randomize Tweets Error:", err.message);
            setError(
                err.response?.data?.message || "Failed to randomize tweets"
            );
        }
    };

    // Handle deletion of a tweet
    const handleDelete = async (tweetId) => {
        if (!window.confirm("Are you sure you want to delete this tweet?"))
            return;

        try {
            setError(null);
            await api.delete(API_ENDPOINTS.DELETE_TWEET(wallId, tweetId));
            setTweets(tweets.filter((tweet) => tweet.id !== tweetId));
        } catch (err) {
            console.error("Delete Tweet Error:", err.message);
            setError(err.response?.data?.message || "Failed to delete tweet");
        }
    };

    const handleDragEnd = async (event) => {
        const { active, over } = event;

        if (active.id === over.id) return;
        const oldIndex = Tweets.findIndex(
            (tweet) => tweet.id === active.id
        );
        const newIndex = Tweets.findIndex((tweet) => tweet.id === over.id);

        // Reorder tweets locally
        const reorderTweets = Array.from(tweets);
        const [movedTweet] = updatedTweets.splice(oldIndex, 1);
        reorderTweets.splice(newIndex, 0, movedTweet);

        // Update order values based on new positions
        const updatedTweets = reorderTweets.map((tweet, index) => ({
            ...tweet,
            order: index, // Assign new order based on array index
        }));

        setTweets(updatedTweets);

        // Prepare data for backend
        const reorderData = updatedTweets.map((tweet) => ({
            id: tweet.id,
            order: tweet.order,
        }));

        try {
            setError(null);
            await api.patch(API_ENDPOINTS.REORDER_TWEETS(wallId), {reorderData});
            setTweets(tweets.filter((tweet) => tweet.id !== tweetId));
        } catch (err) {
            console.error('Error reordering tweets:', error);
            setError(err.response?.data?.message || "Failed to delete tweet");
        }
    };

    // Loading and error states
    if (loading)
        return (
            <div className="text-center p-6 text-gray-500">
                Loading tweets...
            </div>
        );
    if (error)
        return <div className="text-center p-6 text-red-500">{error}</div>;

    return (
        <div className="p-6">
            {/* Randomize Button */}
            <div className="flex justify-end mb-4">
                <button
                    onClick={handleRandomize}
                    className="bg-blue-500 text-white px-4 py-2 rounded hover:bg-blue-600 transition disabled:bg-gray-400 disabled:cursor-not-allowed"
                    disabled={tweets.length === 0 || loading}
                >
                    Randomize Tweets
                </button>
            </div>

            {tweets.length === 0 ? (
                <div className="text-center p-6 text-gray-500">
                    No tweets added yet.
                </div>
            ) : (
                <DndContext
                    onDragEnd={handleDragEnd}
                    collisionDetection={closestCorners}
                >
                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
                        <SortableContext
                            items={tweets}
                            strategy={verticalListSortingStrategy}
                        >
                            {tweets.map((tweet) => (
                                <TweetCard
                                    id={tweet.id}
                                    key={tweet.id}
                                    tweet={tweet}
                                    onDelete={handleDelete}
                                />
                            ))}
                        </SortableContext>
                    </div>
                </DndContext>
            )}
        </div>
    );
};

export default TweetList;
